using NovaHarvest.Core.Events; namespace NovaHarvest.Core.Systems; public sealed class EventSystem { readonly Random _random; public EventSystem(int? seed=null){_random=seed.HasValue?new Random(seed.Value):new Random();} public GameEvent? RollNightEvent(){var r=_random.Next(100);if(r<55)return null;if(r<70)return new GameEvent(GameEventType.MeteorShower,"Chuva de Meteoros","Fragmentos alienígenas caíram durante a noite.",1);if(r<82)return new GameEvent(GameEventType.AlienSignal,"Sinal Desconhecido","Um sinal foi detectado além das montanhas.",1);if(r<94)return new GameEvent(GameEventType.MobMigration,"Migração dos Mobs","Criaturas estão se aproximando da fazenda.",2);return new GameEvent(GameEventType.NightInvasion,"INVASÃO NOTURNA","Uma horda está vindo em direção à colônia.",3);} }
